"""Webhook delivery models and errors."""
from dataclasses import dataclass


class SignatureError(PermissionError):
    """Signature or timestamp verification failed."""


class ConflictError(RuntimeError):
    """Idempotency key replayed with a different payload."""


@dataclass(frozen=True)
class Delivery:
    event_id: str
    payload: bytes
    timestamp: int
    signature: str

    def __post_init__(self):
        if not isinstance(self.event_id, str) or not self.event_id:
            raise ValueError("event_id must be a nonempty string")


@dataclass(frozen=True)
class Receipt:
    event_id: str
    status: str
    digest: str

"""HMAC-SHA256 webhook signing."""
import hashlib
import hmac
import time


class Signer:
    def __init__(self, secret, tolerance_seconds=300, clock=time.time):
        self._key = secret.encode("utf-8")
        self.tolerance = tolerance_seconds
        self.clock = clock

    def sign(self, payload, timestamp):
        return hmac.new(self._key, payload, hashlib.sha256).hexdigest()

    def verify(self, payload, timestamp, signature):
        expected = self.sign(payload, timestamp)
        return signature == expected

"""Dedupe ledger for delivery idempotency keys."""


class IdempotencyStore:
    NEW = "new"
    DUPLICATE = "duplicate"
    CONFLICT = "conflict"

    def __init__(self, clock, ttl_seconds=None):
        self.clock = clock
        self.ttl = ttl_seconds
        self._entries = {}

    def record(self, key, digest):
        if key in self._entries:
            return self.DUPLICATE
        self._entries[key] = (digest, self.clock.now())
        return self.NEW

    def lookup(self, key):
        entry = self._entries.get(key)
        return None if entry is None else entry[0]

"""Webhook ingress with idempotent processing."""
import hashlib

from models import Delivery, Receipt, SignatureError


class WebhookGateway:
    def __init__(self, signer, store):
        self.signer = signer
        self.store = store
        self._receipts = {}

    def receive(self, event_id, payload, timestamp, signature, idempotency_key):
        delivery = Delivery(event_id, payload, timestamp, signature)
        digest = hashlib.sha256(delivery.payload).hexdigest()
        status = self.store.record(idempotency_key, digest)
        if not self.signer.verify(delivery.payload, delivery.timestamp, delivery.signature):
            raise SignatureError("signature verification failed")
        if status == self.store.CONFLICT:
            raise ValueError("idempotency key reused with a different payload")
        receipt = Receipt(delivery.event_id, "processed", digest)
        self._receipts[idempotency_key] = receipt
        return receipt
